namespace Operative.Api.Domain.Entities;

public sealed class DiceRoll
{
    public Guid Id { get; private set; }
    public Guid UserId { get; private set; }
    public int Die1 { get; private set; }
    public int Die2 { get; private set; }
    public int Sum { get; private set; }
    public DateTime CreatedAtUtc { get; private set; }

    private DiceRoll()
    {
    }

    public DiceRoll(Guid userId, int die1, int die2)
    {
        if (userId == Guid.Empty)
        {
            throw new ArgumentException("A dice roll must belong to a user.", nameof(userId));
        }

        if (die1 is < 1 or > 6)
        {
            throw new ArgumentOutOfRangeException(nameof(die1), "A die value must be between 1 and 6.");
        }

        if (die2 is < 1 or > 6)
        {
            throw new ArgumentOutOfRangeException(nameof(die2), "A die value must be between 1 and 6.");
        }

        Id = Guid.NewGuid();
        UserId = userId;
        Die1 = die1;
        Die2 = die2;
        Sum = die1 + die2;
        CreatedAtUtc = DateTime.UtcNow;
    }
}

namespace Shared.Contracts;

public sealed class ApiException : Exception
{
    public int StatusCode { get; }

    public ApiException(string message, int statusCode = 500)
        : base(message)
    {
        StatusCode = statusCode;
    }

    public ApiException(string message, Exception innerException, int statusCode = 500)
        : base(message, innerException)
    {
        StatusCode = statusCode;
    }
}

public sealed record ApiResponse<T>(T Data, string Message, DateTimeOffset Timestamp)
{
    public static ApiResponse<T> Ok(T data, string message = "Request completed successfully.") =>
        new(data, message, DateTimeOffset.UtcNow);
}

public sealed record ErrorResponse(string Message, int StatusCode, string? TraceId = null)
{
    public static ErrorResponse FromException(Exception exception, int statusCode = 500, string? traceId = null) =>
        new(exception.Message, statusCode, traceId ?? Guid.NewGuid().ToString("N"));
}

